public class InnerDataAutomationProjectTranscriptConfigurationFactory(Action<Humidifier.Bedrock.DataAutomationProjectTypes.TranscriptConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.Bedrock.DataAutomationProjectTypes.TranscriptConfiguration>
{

    internal InnerDataAutomationProjectChannelLabelingConfigurationFactory ChannelLabelingFactory { get; set; }

    internal InnerDataAutomationProjectSpeakerLabelingConfigurationFactory SpeakerLabelingFactory { get; set; }

    protected override Humidifier.Bedrock.DataAutomationProjectTypes.TranscriptConfiguration Create()
    {
        var transcriptConfigurationResult = CreateTranscriptConfiguration();
        factoryAction?.Invoke(transcriptConfigurationResult);

        return transcriptConfigurationResult;
    }

    private Humidifier.Bedrock.DataAutomationProjectTypes.TranscriptConfiguration CreateTranscriptConfiguration()
    {
        var transcriptConfigurationResult = new Humidifier.Bedrock.DataAutomationProjectTypes.TranscriptConfiguration();

        return transcriptConfigurationResult;
    }
    public override void CreateChildren(Humidifier.Bedrock.DataAutomationProjectTypes.TranscriptConfiguration result)
    {
        base.CreateChildren(result);

        result.ChannelLabeling ??= ChannelLabelingFactory?.Build();
        result.SpeakerLabeling ??= SpeakerLabelingFactory?.Build();
    }

} // End Of Class

